import { mkdir, readFile, writeFile } from 'node:fs/promises';

const read = async path => (await readFile(new URL(path, import.meta.url), 'utf8')).replaceAll('\r\n', '\n');
const colors = JSON.parse(await read('./src/palette.json'));

function theme(selector, mode) {
  const tokens = Object.entries(colors).map(([name, values]) => `  --ds-${name}: ${values[mode]};`);
  return [`${selector} {`, `  --ds-color-scheme: ${mode};`, ...tokens, '}'].join('\n');
}

const css = [
  '/* Generated by desktop-settings-css. Edit the library sources and rebuild. */',
  theme(':where(.ds-settings)', 'light'),
  '@media (prefers-color-scheme: dark) {\n' +
    theme(':where(.ds-settings:not([data-theme="light"]))', 'dark') + '\n}',
  theme(':where(.ds-settings[data-theme="dark"])', 'dark'),
  await read('./src/base.css'),
  await read('./src/layout.css'),
  await read('./src/components.css'),
  await read('./src/dialog.css'),
  await read('./src/list.css'),
  await read('./src/tooltip.css'),
  await read('./src/menu.css'),
  await read('./src/info-bar.css')
].join('\n\n');

await mkdir(new URL('./dist/', import.meta.url), { recursive: true });
await writeFile(new URL('./dist/settings.css', import.meta.url), css);
console.log(`Built dist/settings.css (${Buffer.byteLength(css)} bytes)`);

for (const [name, exports] of [
  ['inputs', 'bindPathPicker, bindShortcutInput, bindPasswordInput, bindColorInput, createTagInput'],
  ['select', 'createSelect, bindEditableSelect'],
  ['dialog', 'showModal, showAlert, showConfirm, showPrompt'],
  ['tooltip', 'setTooltip, clearTooltip'],
  ['menu', 'createMenuBar, bindContextMenu'],
  ['info-bar', 'createInfoBar']
]) {
  const source = await read(`./src/${name}.js`);
  await writeFile(new URL(`./dist/${name}.mjs`, import.meta.url), `${source}\nexport { ${exports} };\n`);
  await writeFile(new URL(`./dist/${name}.browser.js`, import.meta.url),
    `(() => {\n'use strict';\n${source}\nwindow.DesktopSettings = Object.assign(window.DesktopSettings || {}, { ${exports} });\n})();\n`);
  console.log(`Built dist/${name}.mjs and dist/${name}.browser.js`);
}
